        bool merged = true;

        while (merged) {
            merged = false;
            for (int i = 0; i < result.size(); i++) {
                for (int j = i + 1; j < result.size(); j++) {
                    if (result[i][0] <= result[j][1] && result[j][0] <= result[i][1]) {
                        result[i] = {
                            min(result[i][0], result[j][0]),
