class Solution {
public:
    pair<int, int> findMissingAndRepeating(vector<int>& arr) {
        int n = arr.size();
        long long S = 0, S2 = 0;
        for (int x : arr) {
            S += x;
            S2 += (long long)x * x;
        }
        long long Sn = (long long)n * (n + 1) / 2;
        long long S2n = (long long)n * (n + 1) * (2 * n + 1) / 6;
        long long diff = S - Sn;
        long long sum_xy = (S2 - S2n) / diff;
        int x = (diff + sum_xy) / 2;
        int y = sum_xy - x;
        return {x, y};
    }
};

