        # Store all values
        values = []
        current = head
        while current:
            values.append(current.val)
            current = current.next

        # Reverse in groups of k
        for i in range(0, len(values), k):
            if i + k <= len(values):
                values[i:i+k] = reversed(values[i:i+k])

        # Rebuild linked list
