class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        vector<int> values;
        ListNode* current = head;
        while (current) {
            values.push_back(current->val);
            current = current->next;
        }

        for (int i = 0; i < values.size(); i += k) {
            if (i + k <= values.size()) {
                reverse(values.begin() + i, values.begin() + i + k);
            }
        }

        ListNode* dummy = new ListNode(0);
        current = dummy;
        for (int val : values) {
            current->next = new ListNode(val);
            current = current->next;
        }

        return dummy->next;
    }
};

class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        ListNode* dummy = new ListNode(0, head);
        ListNode* groupPrev = dummy;

        while (true) {
            // Check if k nodes exist
            ListNode* kth = groupPrev;
            for (int i = 0; i < k; i++) {
                kth = kth->next;
                if (!kth) return dummy->next;
            }

            ListNode* groupNext = kth->next;
            ListNode* prev = groupNext;
            ListNode* curr = groupPrev->next;
            groupPrev->next = kth; // Connect to reversed group

            // Reverse the group
            while (curr != groupNext) {
                ListNode* nextNode = curr->next;
                curr->next = prev;
                prev = curr;
                curr = nextNode;
            }

            // Move group_prev to the end of reversed group
            groupPrev = groupPrev->next; // This is now the tail of reversed group
        }

        return dummy->next;
    }
};

