class Solution {
public:
    bool isPalindrome(ListNode* head) {
        stack<int> stk;
        ListNode* current = head;
        while (current) {
            stk.push(current->val);
            current = current->next;
        }

        current = head;
        while (current) {
            if (current->val != stk.top()) return false;
            stk.pop();
            current = current->next;
        }

        return true;
    }
};

