// Brute Force - Rebuild from scratch - O(n) time, O(n) space
class Solution {
public:
    Node* flatten(Node* head) {
        vector<int> values;

        function<void(Node*)> collect = [&](Node* node) {
            while (node) {
                values.push_back(node->val);
                if (node->child) collect(node->child);
                node = node->next;
            }
        };

        collect(head);

        if (values.empty()) return nullptr;

        Node* dummy = new Node(0);
        Node* current = dummy;
        for (int val : values) {
            Node* newNode = new Node(val);
            current->next = newNode;
            newNode->prev = current;
            current = current->next;
        }

        dummy->next->prev = nullptr;
        return dummy->next;
    }
};

class Solution {
public:
    Node* flatten(Node* head) {
        if (!head) return nullptr;

        Node* dummy = new Node(0);
        Node* prev = dummy;
        stack<Node*> stk;
        stk.push(head);

        while (!stk.empty()) {
            Node* curr = stk.top();
            stk.pop();

            // Link the node to the flattened list
            prev->next = curr;
            curr->prev = prev;

            // Push next node first so child is processed first (stack is LIFO)
            if (curr->next) stk.push(curr->next);

            // Push child to be processed before next
            if (curr->child) {
                stk.push(curr->child);
                curr->child = nullptr; // Remove child pointer
            }

            prev = curr;
        }

        dummy->next->prev = nullptr;
        return dummy->next;
    }
};

class Solution {
public:
    Node* flatten(Node* head) {
        function<Node*(Node*)> flatten_dfs = [&](Node* node) -> Node* {
            Node* curr = node;
            Node* last = node;

            while (curr) {
                if (curr->child) {
                    Node* childTail = flatten_dfs(curr->child);

                    Node* nextNode = curr->next;

                    curr->next = curr->child;
                    curr->child->prev = curr;
                    curr->child = nullptr;

                    childTail->next = nextNode;
                    if (nextNode) nextNode->prev = childTail;

                    last = childTail;
                    curr = nextNode;
                } else {
                    last = curr;
                    curr = curr->next;
                }
            }

            return last;
        };

        flatten_dfs(head);
        return head;
    }
};

