class Solution:
    def rotateRight(self, head, k):
        if not head or not head.next or k == 0:
            return head

        length = 0
        current = head
        while current:
            length += 1
            current = current.next

        k = k % length
        if k == 0:
            return head

        for _ in range(k):
            prev = None
            current = head
            while current.next:
                prev = current
                current = current.next
            current.next = head
            prev.next = None
            head = current

        return head

