class Solution:
    def power(self, x, n, m):
        result = 1
        base = x
        while n > 0:
            if n % 2 == 1:
                result *= base
                if result > m:
                    return m + 1
            base *= base
            if base > m and n > 1:
                return m + 1
            n //= 2
        return result

    def nthRoot(self, n, m):
        low, high = 1, m
        while low <= high:
            mid = (low + high) // 2
            val = power(mid, n, m)
            if val == m:
                return mid
            elif val < m:
                low = mid + 1
            else:
                high = mid - 1
        return -1

