class Solution:
    def countSmallerThanOrEqual(self, row, target):
        lo, hi = 0, len(row)
        while lo < hi:
            mid = (lo + hi) // 2
            if row[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def median(self, matrix):
        R, C = len(matrix), len(matrix[0])
        low = min(row[0] for row in matrix)
        high = max(row[-1] for row in matrix)
        desired = (R * C) // 2

        while low <= high:
            mid = (low + high) // 2
            count = sum(countSmallerThanOrEqual(row, mid) for row in matrix)
            if count <= desired:
                low = mid + 1
            else:
                high = mid - 1

        return low

