class Solution:
    def isPossible(self, arr, k, maxPages):
        students, currentSum = 1, 0
        for pages in arr:
            if currentSum + pages > maxPages:
                students += 1
                currentSum = pages
            else:
                currentSum += pages
        return students <= k

