        pivot_idx = random.randint(left, right)
        pivot_idx = partition(left, right, pivot_idx)

        if k_smallest == pivot_idx:
            return
        elif k_smallest < pivot_idx:
            self.quickselect(left, pivot_idx - 1, k_smallest)
        else:
            self.quickselect(pivot_idx + 1, right, k_smallest)


    def partition(self, left, right, pivot_idx):
        pivot_freq = count[unique[pivot_idx]]
        unique[pivot_idx], unique[right] = unique[right], unique[pivot_idx]
        store_idx = left

        for i in range(left, right):
            if count[unique[i]] < pivot_freq:
                unique[store_idx], unique[i] = unique[i], unique[store_idx]
                store_idx += 1

        unique[store_idx], unique[right] = unique[right], unique[store_idx]
        return store_idx


    def topKFrequent(self, nums: list[int], k: int) -> list[int]:
        count = Counter(nums)
        unique = list(count.keys())

        n = len(unique)
        self.quickselect(0, n - 1, n - k)
        return unique[n - k:]

