class Solution:
    def search(self, pat, txt):
        d = 256  # number of characters in the alphabet
        q = 101  # a prime number for modulo hashing
        m, n = len(pat), len(txt)
        results = []

        if m > n:
            return results

        p_hash = 0  # hash value for pattern
        t_hash = 0  # hash value for current window
        h = 1

        # h = d^(m-1) % q
        for i in range(m - 1):
            h = (h * d) % q

        # Compute initial hash values
        for i in range(m):
            p_hash = (d * p_hash + ord(pat[i])) % q
            t_hash = (d * t_hash + ord(txt[i])) % q

        # Slide the pattern over the text
        for i in range(n - m + 1):
            if p_hash == t_hash:
                # Hash match, verify character by character
                match = True
                for j in range(m):
                    if txt[i + j] != pat[j]:
                        match = False
                        break
                if match:
                    results.append(i)

            # Compute hash for next window
            if i < n - m:
                t_hash = (d * (t_hash - ord(txt[i]) * h) + ord(txt[i + m])) % q
                if t_hash < 0:
                    t_hash += q

        return results

