                q.pop();

                unsigned long long normalizedIdx = idx - minIdx;

                if (node->left) q.push({node->left, 2 * normalizedIdx + 1});
                if (node->right) q.push({node->right, 2 * normalizedIdx + 2});
            }
        }

        return maxWidth;
    }
};

