    def helper(self, i):
        if i == 0:
            return (nums[0], nums[0])
        prev_max, prev_min = self.helper(i - 1)
        curr_max = max(nums[i], nums[i] * prev_max, nums[i] * prev_min)
        curr_min = min(nums[i], nums[i] * prev_max, nums[i] * prev_min)
        return (curr_max, curr_min)


